WITH kept_keys AS (SELECT brand, category FROM products EXCEPT DISTINCT SELECT brand, category FROM products WHERE brand IN ('Stark', 'Umbrella', 'Initech')), reconciled AS (SELECT s.* FROM products s INNER JOIN kept_keys k ON s.brand = k.brand AND s.category = k.category) SELECT DATE_TRUNC('MONTH', launch_date) AS activity_month, SUM(cost) AS total_cost, AVG(stock_qty) AS avg_stock_qty, MAX(cost) FILTER (WHERE category = 'Home') AS home_max_cost, STDDEV_SAMP(stock_qty) AS stock_qty_stddev, SORT_ARRAY(COLLECT_SET(brand)) AS brand_list, PERCENTILE_APPROX(price, 0.9) AS price_p90 FROM reconciled GROUP BY DATE_TRUNC('MONTH', launch_date) HAVING MAX(cost) FILTER (WHERE category = 'Home') < 0;
